The action for the description field of a published course:

export async function saveDescription(id: string, description: string) {
  await db.course.update({ where: { id }, data: { description } });
  updateTag(`course:${id}`);
}

Statement: "After this action, every cached entry that contains the old description has been expired, although courses:list and the category tags were not touched."

